class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        Map<Node, Node> copies = new HashMap<>();
        Node curr = head;
        while (curr != null) {
            copies.put(curr, new Node(curr.val));
            curr = curr.next;
        }

        curr = head;
        while (curr != null) {
            Node copy = copies.get(curr);
            copy.next = copies.get(curr.next);
            copy.random = copies.get(curr.random);
            curr = curr.next;
        }

        return copies.get(head);
    }
}

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        Node curr = head;
        while (curr != null) {
            Node copy = new Node(curr.val);
            copy.next = curr.next;
            curr.next = copy;
            curr = copy.next;
        }

        curr = head;
        while (curr != null) {
            if (curr.random != null) {
                curr.next.random = curr.random.next;
            }
            curr = curr.next.next;
        }

        Node dummy = new Node(0);
        Node copyTail = dummy;
        curr = head;
        while (curr != null) {
            Node copy = curr.next;
            Node nextOriginal = copy.next;
            copyTail.next = copy;
            copyTail = copy;
            curr.next = nextOriginal;
            curr = nextOriginal;
        }
        return dummy.next;
    }
}

class Solution {
    private Map<Node, Node> seen = new HashMap<>();

    public Node copyRandomList(Node head) {
        return clone(head);
    }

    private Node clone(Node node) {
        if (node == null) {
            return null;
        }
        if (seen.containsKey(node)) {
            return seen.get(node);
        }
        Node copy = new Node(node.val);
        seen.put(node, copy);
        copy.next = clone(node.next);
        copy.random = clone(node.random);
        return copy;
    }
}

class Solution {
    public Node copyRandomList(Node head) {
        Map<Node, Node> copies = new HashMap<>();
        Node curr = head;
        while (curr != null) {
            Node copy = getCopy(curr, copies);
            copy.next = getCopy(curr.next, copies);
            copy.random = getCopy(curr.random, copies);
            curr = curr.next;
        }
        return getCopy(head, copies);
    }

    private Node getCopy(Node node, Map<Node, Node> copies) {
        if (node == null) {
            return null;
        }
        Node copy = copies.get(node);
        if (copy == null) {
            copy = new Node(node.val);
            copies.put(node, copy);
        }
        return copy;
    }
}
